const openRestorePicker=()=>{try{if(window.GhazayarNative&&typeof window.GhazayarNative.openBackup==='function'){window.GhazayarNative.openBackup();return;}$('#restoreFile')?.click();}catch(error){console.error(error);notify('باز کردن فایل پشتیبان ممکن نشد.');}};$('#dashboardBackupBtn')?.addEventListener('click',e=>{e.preventDefault();backup();});$('#dashboardRestoreBtn')?.addEventListener('click',e=>{e.preventDefault();openRestorePicker();});$('#restoreFile')?.addEventListener('change',restore);
