 if(has('سمبوسه'))return ['مواد میانی را ریز خرد کنید و با پیاز و ادویه تفت دهید تا آب اضافی گرفته شود؛ اجازه دهید خنک شود تا نان خمیر نشود.','نان را به نوارهای پهن ببرید، یک قاشق از مواد را در گوشه بگذارید و مثلثی تا بزنید؛ لبه آخر را با خمیر آرد و آب بچسبانید.','سمبوسه را در روغن متوسط از دو طرف طلایی کنید یا در فر بپزید؛ روی دستمال بگذارید و گرم سرو کنید.'];
 if(has('پیتزا'))return ['خمیر را روی سطح آردپاشی‌شده باز کنید و روی سینی چرب‌شده بگذارید. سس گوجه و کمی پنیر روی آن پخش کنید.','قارچ و فلفل دلمه‌ای را کمی تفت دهید تا آب اضافی گرفته شود؛ پپرونی یا مرغ و باقی پنیر را یکنواخت پخش کنید.','در فر از پیش گرم‌شده با دمای ۲۰۰ تا ۲۲۰ درجه بپزید تا لبه خمیر طلایی و پنیر حباب‌دار شود؛ کمی استراحت دهید و برش بزنید.'];
 if(has('لازانیا'))return ['پیاز و گوشت چرخ‌کرده را تفت دهید، قارچ را اضافه کنید و صبر کنید آبش کشیده شود؛ سس گوجه را بیفزایید و مایه را غلیظ کنید.','سس بشامل را با کره، آرد و شیر آماده کنید. ورق لازانیا را طبق دستور بسته نرم کنید؛ در ظرف فر بشامل، ورق، مایه گوشت و پنیر را لایه‌لایه بچینید.','روی ظرف پنیر بریزید و با فویل در فر ۱۸۰ درجه حدود ۲۵ دقیقه بپزید؛ فویل را بردارید تا پنیر طلایی شود. پیش از برش ۱۰ دقیقه استراحت دهید.'];
 if(has('آلفردو')||has('پاستا'))return ['پاستا را در آب جوش نمک‌دار تا مرحله آل‌دنته بپزید و کمی از آب پخت را نگه دارید. مرغ را نواری کنید و با نمک و فلفل تفت دهید تا مغزپخت شود.','سیر را کوتاه تفت دهید؛ خامه و پارمزان را با حرارت ملایم اضافه کنید تا سس یکدست شود. پاستا و مرغ را داخل سس بریزید و در صورت نیاز آب پاستا اضافه کنید.','سس را فقط تا حد چسبیدن به پاستا گرم کنید و نجوشانید؛ با جعفری و پارمزان سرو کنید.'];
 if(has('کیک','رولت','تارت','باقلوا','شیرینی','وافل','پنکیک'))return ['مواد خشک شامل آرد و بیکینگ‌پودر را الک کنید. تخم‌مرغ و شکر را جداگانه بزنید تا روشن و حجیم شود؛ سپس کره و شیر را اضافه کنید.','مایه را فقط تا یکدست شدن مخلوط کنید و در قالب چرب‌شده بریزید. برای تارت، خمیر را سرد استراحت دهید؛ برای رولت، لایه کیک را نازک و یکنواخت بپزید.','در فر از پیش گرم‌شده بپزید تا خلال چوبی تمیز بیرون بیاید؛ پس از خنک شدن با خامه، شکلات یا میوه تزیین کنید.'];
 if(has('اسموتی','شیرموز','آب طالبی'))return ['میوه را خرد کنید و شیر یا ماست را سرد نگه دارید؛ مغزیجات را درشت خرد کنید.','میوه و مایع سرد را در مخلوط‌کن بریزید؛ عسل را کم‌کم اضافه کنید و فقط تا یکدست شدن بزنید. برای غلظت بیشتر یخ یا میوه یخ‌زده اضافه کنید.','در لیوان سرد بریزید و با مغزیجات یا تکه میوه تزیین کنید؛ بلافاصله سرو کنید.'];
 if(has('پاپ‌کورن'))return ['قابلمه دردار را با کمی روغن گرم کنید. دو دانه ذرت بیندازید و پس از ترکیدن، باقی ذرت را اضافه کنید.','در قابلمه را ببندید و هر چند ثانیه تکان دهید؛ وقتی فاصله ترکیدن‌ها چند ثانیه شد از روی حرارت بردارید.','نمک و ادویه را در حالی که ذرت گرم است اضافه کنید و در ظرف باز سرو کنید.'];
 if(has('لوبیا پلو'))return ['لوبیا سبز را خرد کنید و چند دقیقه در آب جوش نیم‌پز کنید. پیاز را طلایی کنید، گوشت چرخ‌کرده را با زردچوبه تفت دهید و لوبیا را اضافه کنید.','رب گوجه، فلفل و کمی دارچین را اضافه کنید و مایه را با حرارت ملایم بپزید تا آب اضافی آن کشیده شود. برنج خیس‌خورده را جداگانه در آب جوش نیم‌پز و آبکش کنید.','برنج و مایه لوبیا را لایه‌لایه در قابلمه بریزید و با دم‌کنی حدود ۴۰ دقیقه دم کنید؛ هنگام سرو زعفران و سیب‌زمینی ته‌دیگ را اضافه کنید.'];
 if(has('عدس پلو'))return ['عدس را جداگانه با آب بپزید تا نرم شود اما له نشود. پیاز را خلالی طلایی کنید؛ گوشت قلقلی را با نمک، فلفل و زردچوبه شکل دهید و سرخ یا در سس بپزید.','برنج را در آب جوش نیم‌پز و آبکش کنید. کشمش را با کمی روغن و دارچین فقط یک تا دو دقیقه تفت دهید تا نسوزد.','برنج، عدس، دارچین و بخشی از پیازداغ را لایه‌لایه دم کنید؛ با گوشت قلقلی، کشمش و پیازداغ سرو کنید.'];
 if(has('استانبولی'))return ['سیب‌زمینی را مکعبی خرد کنید. پیاز را تفت دهید، سیب‌زمینی و زردچوبه را اضافه کنید و کمی سرخ کنید؛ سپس رب را اضافه کنید تا بوی خامی آن گرفته شود.','گوجه خردشده یا پوره گوجه را اضافه کنید و بگذارید سس غلیظ شود. برنج شسته را همراه آب متناسب با روش کته و نمک داخل قابلمه بریزید.','وقتی آب برنج تقریباً کشیده شد، حرارت را کم کنید و با دم‌کنی حدود ۳۰ تا ۴۰ دقیقه دم بگذارید؛ با ماست یا ترشی سرو کنید.'];
 if(has('باقالی پلو'))return ['باقالی سبز را چند دقیقه در آب جوش نیم‌پز و آبکش کنید. شوید تازه را خرد کنید؛ اگر از باقالی خشک استفاده می‌کنید، زمان پخت بیشتری در نظر بگیرید.','گوشت ماهیچه را با پیاز، زردچوبه و فلفل تفت دهید، آب جوش اضافه کنید و با شعله کم بپزید تا کاملاً نرم شود؛ برای نسخه مرغ، مرغ را جداگانه با زعفران بپزید.','برنج را نیم‌پز و آبکش کنید؛ آن را لایه‌لایه با باقالی و شوید دم کنید. در پایان زعفران و کره اضافه کرده و همراه گوشت یا مرغ سرو کنید.'];
 if(has('آلبالو پلو'))return ['آلبالوها را هسته‌گیری کنید و با کمی شکر چند دقیقه روی حرارت ملایم قرار دهید تا آب بیندازند؛ سپس آب اضافی را جداگانه نگه دارید.','گوشت چرخ‌کرده را با پیاز رنده‌شده، نمک و فلفل ورز دهید و قلقلی‌های کوچک درست کنید؛ آن‌ها را سرخ کنید تا مغزپخت شوند.','برنج را نیم‌پز و آبکش کنید و با لایه‌های آلبالو و گوشت قلقلی دم بگذارید؛ در پایان کمی زعفران و از شربت آلبالو به اندازه دلخواه اضافه کنید.'];
 if(has('آبگوشت')||has('دیزی'))return ['نخود و لوبیا را از شب قبل خیس کنید و آب آن را عوض کنید. گوشت با استخوان، حبوبات، پیاز چهارقاچ و زردچوبه را در قابلمه بریزید و آب سرد اضافه کنید.','پس از جوش آمدن کف روی آب را بگیرید و شعله را بسیار کم کنید؛ حدود ۲ تا ۳ ساعت آرام بپزید. سپس سیب‌زمینی و گوجه یا رب را اضافه کنید تا همه مواد نرم شوند.','نمک و لیموعمانی را در نیم‌ساعت پایانی اضافه کنید. آبگوشت را جدا در کاسه بکشید و گوشت و حبوبات را برای کوبیدن در دیزی‌سنگی یا کاسه آماده کنید.'];
 if(has('آش رشته'))return ['نخود و لوبیا را از شب قبل خیس کنید و جداگانه نیم‌پز کنید. پیاز را خلالی سرخ کنید؛ بخشی از آن را برای تزیین کنار بگذارید.','حبوبات، عدس و سبزی آش خردشده را با آب در قابلمه بپزید. پس از نرم شدن سبزی، رشته آش را خرد کرده و کم‌کم اضافه کنید و مرتب هم بزنید تا به هم نچسبد.','کشک را در پایان اضافه کنید و چند دقیقه بجوشانید؛ غلظت را با آب جوش تنظیم کنید و با پیازداغ، نعناع‌داغ و کشک تزیین کنید.'];
 if(has('میرزا قاسمی'))return ['بادمجان‌ها را روی شعله یا در فر کباب کنید تا پوستشان بسوزد و مغز کاملاً نرم شود؛ پوست را جدا کنید و گوشت بادمجان را ساطوری کنید.','سیر خردشده را با روغن کوتاه تفت دهید، زردچوبه و گوجه پوست‌گرفته و خردشده را اضافه کنید تا آب گوجه کشیده شود؛ بادمجان را مخلوط کنید.','مواد را کنار بزنید، تخم‌مرغ‌ها را اضافه کنید و هم بزنید تا ببندند؛ نمک را تنظیم کنید و با نان یا برنج سرو کنید.'];
 if(has('کشک بادمجان'))return ['بادمجان‌ها را پوست بگیرید، ورقه کنید و کمی نمک بزنید؛ پس از خشک کردن با روغن کم سرخ یا در فر کباب کنید. پیاز را جداگانه طلایی کنید.','بادمجان را با گوشت‌کوب له کنید و همراه بخشی از پیازداغ، سیر و نعناع‌داغ چند دقیقه تفت دهید؛ کمی آب اضافه کنید تا بافت یکدست شود.','کشک رقیق‌شده را اضافه کنید و چند دقیقه روی حرارت ملایم بجوشانید؛ با گردو، پیازداغ و نعناع‌داغ تزیین کنید.'];
 if(has('کوکو سبزی'))return ['سبزی کوکو را ریز خرد کنید و آب اضافی آن را بگیرید. تخم‌مرغ‌ها را با نمک، فلفل، زردچوبه و کمی آرد یا زرشک و گردو در صورت تمایل هم بزنید.','سبزی را با مایه تخم‌مرغ مخلوط کنید. تابه نچسب را چرب و گرم کنید، مایه را یکدست پهن کنید و در تابه را بگذارید تا زیر آن ببندد.','کوکو را به قطعات تقسیم و برگردانید تا طرف دیگر نیز طلایی شود؛ برای پخت یکنواخت می‌توانید در فر ۱۸۰ درجه بپزید و با ماست سرو کنید.'];
 if(has('کتلت'))return ['سیب‌زمینی و پیاز را رنده کنید و آب اضافی‌شان را کاملاً بگیرید. گوشت چرخ‌کرده، تخم‌مرغ، زردچوبه، نمک و فلفل را اضافه کنید و ورز دهید.','از مایه، کتلت‌های نازک و بیضی‌شکل درست کنید؛ اگر مایه شل است کمی آرد سوخاری اضافه کنید و ۱۵ دقیقه در یخچال استراحت دهید.','کتلت‌ها را در روغن با حرارت متوسط سرخ کنید؛ هر طرف را تا طلایی شدن بپزید و روی دستمال روغن‌گیر قرار دهید.'];
 if(has('شامی'))return ['لپه را بپزید و آبکش کنید؛ پس از خنک شدن با گوشت چرخ‌کرده و پیاز چرخ کنید تا مایه یکدست شود. تخم‌مرغ، نمک، فلفل و زردچوبه را اضافه کنید.','مایه را خوب ورز دهید و به شکل دایره‌های نازک فرم دهید؛ وسط هر شامی را با انگشت سوراخ کنید تا یکنواخت بپزد.','شامی‌ها را در روغن متوسط از دو طرف سرخ کنید تا مغزپخت شوند؛ با گوجه، سبزی خوردن و نان سرو کنید.'];
 if(has('ماکارونی'))return ['پیاز را نگینی تفت دهید و گوشت چرخ‌کرده را اضافه کنید تا رنگش عوض شود. رب، زردچوبه، فلفل و در صورت تمایل قارچ یا فلفل دلمه‌ای را اضافه کنید و مایه را غلیظ کنید.','ماکارونی را در آب جوش نمک‌دار تا کمی سفت‌تر از حالت دلخواه بجوشانید و آبکش کنید؛ کمی آب سرد روی آن نگیرید تا نشاسته سطحی حفظ شود.','ته قابلمه روغن و سیب‌زمینی یا نان بچینید؛ ماکارونی و مایه را لایه‌لایه بریزید و با دم‌کنی ۳۰ تا ۴۰ دقیقه دم کنید.'];
 if(has('دلمه'))return ['برنج و لپه را جداگانه نیم‌پز کنید. پیاز را تفت دهید و گوشت چرخ‌کرده را اضافه کنید؛ سبزی دلمه خردشده، لپه، برنج و ادویه را مخلوط کنید.','برای برگ مو، برگ‌ها را کوتاه در آب جوش نرم کنید؛ برای فلفل یا بادمجان، داخل آن‌ها را خالی کنید. مواد را بدون فشردن زیاد داخل پوسته‌ها بریزید و ببندید.','دلمه‌ها را فشرده در قابلمه بچینید و سس آب، رب، آب‌لیمو یا سرکه و کمی شکر را اضافه کنید؛ با شعله کم بپزید تا مغز مواد نرم و سس غلیظ شود.'];
 if(has('شیر برنج')||has('شیربرنج'))return ['برنج نیم‌دانه را بشویید و چند ساعت خیس کنید؛ با آب روی حرارت ملایم بپزید تا دانه‌ها کاملاً باز و نرم شوند.','شیر گرم را کم‌کم اضافه کنید و مرتب هم بزنید تا ته نگیرد؛ اجازه دهید با شعله کم به غلظت فرنی برسد. در صورت تمایل شکر و هل اضافه کنید.','گلاب را در چند دقیقه پایانی بیفزایید و پس از غلیظ شدن در ظرف بکشید؛ با دارچین و خلال پسته تزیین کنید.'];
 if(cat==='نوشیدنی')return ['مواد نوشیدنی یعنی '+ing+' را اندازه بگیرید؛ میوه یا گیاه تازه را بشویید و آماده کنید.','پایه را متناسب با نوع نوشیدنی آماده کنید: مواد دم‌کردنی با آب داغ، مواد پودری ابتدا با کمی مایع حل، و نوشیدنی‌های میوه‌ای با مایع سرد ترکیب شوند.','شیرینی، غلظت و دما را تنظیم کنید و در لیوان مناسب با یخ یا تزیین متناسب سرو کنید.'];
 if(cat==='سالاد و پیش‌غذا')return ['سبزیجات و مواد اصلی یعنی '+ing+' را بشویید و کاملاً خشک کنید؛ هر کدام را متناسب با بافتشان خرد کنید.','چاشنی را جداگانه با روغن زیتون و آب‌لیمو یا سرکه هم بزنید؛ مواد سفت‌تر را ابتدا مخلوط و پنیر یا سبزی لطیف را در آخر اضافه کنید.','سس را درست پیش از سرو روی مواد بریزید و آرام زیرورو کنید تا سالاد آب نیندازد؛ با تزیین متناسب سرو کنید.'];
