 content.innerHTML='<span class="eyebrow">'+escapeHtml(category)+' · '+fa(r.time||0)+' دقیقه</span><h2>'+(r.emoji||'🍲')+' '+escapeHtml(name)+'</h2><p>'+escapeHtml(description)+'</p><h3>مواد لازم</h3>'+ingredientHtml+'<h3>طرز تهیه</h3>'+stepsHtml+'<div class="menu-actions"><button class="primary-btn" id="recipePdfBtn">چاپ / ذخیره PDF</button><button class="secondary-btn" id="recipeToShopping" '+(ingredients.length?'':'disabled')+'>افزودن مواد به فهرست خرید</button><button class="secondary-btn" id="saveRecipeFromDialog">'+(state.savedRecipes.includes(r.id)?'حذف از ذخیره‌ها':'ذخیره دستور')+'</button></div>';
