 const isLuxury=/مجلل|رسمی/.test((p.style||'')+' '+(p.type||'')),isTraditional=/سنتی|خانوادگی|خودمانی|مراسم عزا/.test((p.style||'')+' '+(p.type||'')),isCelebration=/جشن|مجلل/.test((p.type||'')+' '+(p.style||''));
